; Title tune and the wait for FIRE, from $4c0e
; $4c0e-$4c27

; Sets $b2 (FIRE pressed on the title), gates off the three voices and waits for a short time.
title_tune_stop
        inc fire_pressed
        lda #$20
        sta VCREG1
        sta VCREG2
        lda #$40
        sta VCREG3
        ldx #$3f
title_tune_stop_delay_outer
        ldy #$ff
title_tune_stop_delay_inner
        dey
        bne title_tune_stop_delay_inner
        dex
        bne title_tune_stop_delay_outer
        rts
